use verus::prelude::*;

// Specification‐only helper functions for max and min of three i8’s
#[verifier(spec)]
fn max2_i8(x: i8, y: i8) -> i8 {
    if x >= y { x } else { y }
}

#[verifier(spec)]
fn max3_i8(x: i8, y: i8, z: i8) -> i8 {
    max2_i8(x, max2_i8(y, z))
}

#[verifier(spec)]
fn min2_i8(x: i8, y: i8) -> i8 {
    if x <= y { x } else { y }
}

#[verifier(spec)]
fn min3_i8(x: i8, y: i8, z: i8) -> i8 {
    min2_i8(x, min2_i8(y, z))
}

verus! {

  /// Given three costs in [1,100], returns max − min ≥ 0 as an i8.
  #[requires(1 <= a1.to_int() && a1.to_int() <= 100)]
  #[requires(1 <= a2.to_int() && a2.to_int() <= 100)]
  #[requires(1 <= a3.to_int() && a3.to_int() <= 100)]
  #[ensures(result.to_int() >= 0)]
  #[ensures(result.to_int() ==
            max3_i8(a1, a2, a3).to_int() -
            min3_i8(a1, a2, a3).to_int())]
  fn solve(a1: i8, a2: i8, a3: i8) -> i8 {
      // Compute the maximum of the three
      let mut mx = a1;
      if a2 > mx {
          mx = a2;
      }
      if a3 > mx {
          mx = a3;
      }

      // Compute the minimum of the three
      let mut mn = a1;
      if a2 < mn {
          mn = a2;
      }
      if a3 < mn {
          mn = a3;
      }

      // mx and mn agree with the spec‐defined max3_i8/min3_i8
      assert(mx.to_int() == max3_i8(a1, a2, a3).to_int());
      assert(mn.to_int() == min3_i8(a1, a2, a3).to_int());

      // mx ≥ mn ⇒ difference is non‐negative
      assert(mx >= mn);

      let diff = mx - mn;
      assert(diff.to_int() >= 0);

      diff
  }

}